cd /root/schema_semantic_constrained_ie && python3 -c "
import json

# SciERC: analyze violation patterns for Compare and Feature-of
with open('outputs/phase2_scierc_unconstrained.jsonl') as f:
    scierc_data = [json.loads(line) for line in f]

with open('ontology_constraints.json') as f:
    scierc_ont = json.load(f)

for target_rel in ['Compare', 'Feature-of']:
    valid_pairs = set(tuple(p) for p in scierc_ont['relation_constraints'][target_rel]['valid_pairs'])
    pair_counts = {}
    violation_pair_counts = {}
    for doc in scierc_data:
        parsed = doc.get('parsed_output', {})
        for rel in parsed.get('relations', []):
            if rel['type'] == target_rel:
                pair = (rel['head_type'], rel['tail_type'])
                pair_counts[pair] = pair_counts.get(pair, 0) + 1
                if pair not in valid_pairs:
                    violation_pair_counts[pair] = violation_pair_counts.get(pair, 0) + 1

    print(f'=== {target_rel} ===')
    print(f'Top predicted pairs:')
    for pair, count in sorted(pair_counts.items(), key=lambda x: -x[1])[:8]:
        is_valid = pair in valid_pairs
        print(f'  {pair[0]} -> {pair[1]}: {count} {\"\" if is_valid else \"[VIOLATION]\"}')
    print(f'Top violation pairs:')
    for pair, count in sorted(violation_pair_counts.items(), key=lambda x: -x[1])[:5]:
        print(f'  {pair[0]} -> {pair[1]}: {count}')
    print()
"
